css:
@page {
  size: A4;
  margin: 5mm 6mm 12mm 6mm;
}

:root {
  --brand: #0f766e;
  --blue: #2f5f9f;
  --soft: #e7f4f2;
  --soft-2: #f3faf9;
  --ink: #12212b;
  --muted: #58707d;
  --line: #d5dde2;
  --card: #ffffff;
}

@font-face {
  font-family: 'CascadiaCode-Bold';
  src: url('/assets/tms/fonts/CascadiaCode-Bold.ttf') format('truetype');
  font-weight: 700;
  font-style: normal;
}

@font-face {
  font-family: 'Noto Naskh Arabic';
  src: url('/assets/tms/fonts/NotoNaskhArabic-VariableFont_wght.ttf') format('truetype');
  font-weight: 400 700;
  font-style: normal;
}

@font-face {
  font-family: 'SaudiRiyalSymbol';
  src: url('/assets/tms/fonts/saudiriyalsymbol.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 0 !important;
}

* {
  box-sizing: border-box;
}

body {
  font-family: Ubuntu, "Segoe UI", Arial, sans-serif;
  font-size: 8.2px;
  color: var(--ink);
}

.quotation-shell {
  position: relative;
}

.sheet {
  position: relative;
  min-height: 278mm;
  padding-bottom: 10mm;
  background: #ffffff;
}

.company-header-box {
  width: 100%;
  border-bottom: 1px solid var(--line);
  padding-bottom: 4px;
  margin-bottom: 4px;
}

.company-header-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.company-header-table td {
  vertical-align: top !important;
  border: 0 !important;
}

.company-info-en {
  width: 36%;
  text-align: left;
  direction: ltr;
  font-size: 9.6px;
  line-height: 1.32;
}

.company-info-ar {
  width: 36%;
  text-align: right;
  direction: rtl;
  font-family: 'Noto Naskh Arabic', serif;
  font-size: 9.7px;
  line-height: 1.32;
}

.company-logo-mid {
  width: 24%;
  text-align: center;
  vertical-align: middle !important;
}

.company-name-en {
  font-size: 12.2px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-name-ar {
  font-size: 12.8px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-line {
  margin-bottom: 1.5px;
}

.company-label {
  font-weight: 600;
  color: var(--brand);
}

.brand-logo-frame {
  display: inline-block;
  min-width: 156px;
  min-height: 82px;
  padding: 1px 3px;
  background: #fff;
  text-align: center;
  vertical-align: middle;
}

.brand-logo {
  display: block;
  max-width: 146px !important;
  max-height: 96px !important;
  width: auto !important;
  height: auto !important;
  margin: 0 auto;
  object-fit: contain;
  vertical-align: middle;
}

.invoice-title-center {
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  margin-top: 4px;
  color: var(--brand);
}

.ar-title {
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
}

.summary-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 3px;
}

.summary-card {
  width: 100%;
  vertical-align: top;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}

.mini-table {
  width: 100%;
  border-collapse: collapse;
}

.mini-table td {
  padding: 1.6px 0 !important;
  border-bottom: 1px dashed var(--line);
  vertical-align: top !important;
  line-height: 1.12;
}

.mini-table tr:last-child td {
  border-bottom: 0;
}

.mini-label {
  width: 33%;
  color: var(--muted);
  font-weight: 400;
}

.mini-value {
  width: 34%;
  font-weight: 500;
}

.mini-ar {
  font-family: 'Noto Naskh Arabic', serif;
  width: 33%;
  text-align: right;
  direction: rtl;
  color: var(--muted);
}

.party-grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-top: 3px;
}

.party-grid > tbody > tr > td {
  border: 0 !important;
  padding: 0 !important;
  vertical-align: top !important;
}

.party-column {
  width: 49%;
}

.party-gap {
  width: 2%;
}

.party-card {
  width: 100%;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
  page-break-inside: avoid;
  break-inside: avoid;
}

.party-title {
  display: table;
  width: 100%;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 3px;
}

.party-title strong {
  display: table-cell;
  color: var(--brand);
  font-size: 9px;
  font-weight: 600;
}

.party-title span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  color: var(--brand);
  direction: rtl;
  text-align: right;
  font-size: 9px;
}

.party-rows {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.party-rows td {
  padding: 1.4px 0 !important;
  border-bottom: 1px dashed var(--line) !important;
  vertical-align: top !important;
  line-height: 1.12;
}

.party-rows tr:last-child td {
  border-bottom: 0 !important;
}

.party-rows td:first-child {
  width: 28%;
  color: var(--muted);
  font-weight: 400;
}

.party-rows td:nth-child(2) {
  width: 46%;
  font-weight: 500;
  padding-right: 8px !important;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.party-rows td:last-child {
  font-family: 'Noto Naskh Arabic', serif;
  width: 26%;
  direction: rtl;
  text-align: right;
  color: var(--muted);
}

.letter-block {
  margin-top: 5px;
  border-top: 1px solid var(--line);
  padding-top: 4px;
}

.top-info {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
}

.top-info td {
  border: 0 !important;
  padding: 2px 0 !important;
  vertical-align: top !important;
  line-height: 1.25;
}

.label-cell {
  width: 72px;
  white-space: nowrap;
}

.value-cell {
  width: auto;
  padding-left: 8px !important;
  overflow-wrap: break-word;
}

.subject-value {
  text-decoration: underline;
}

.dear {
  margin: 5px 0 0 0;
}

.intro {
  margin: 5px 0 0 0;
  line-height: 1.32;
  text-align: left;
}

.intro-small {
  margin: 5px 0 2px 0;
}

.block {
  margin-top: 4px;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}

.block-head {
  display: table;
  width: 100%;
  margin-bottom: 3px;
}

.block-head strong {
  display: table-cell;
  color: var(--brand);
  font-size: 7.6px;
  font-weight: 600;
}

.block-head span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
  text-align: right;
  color: var(--muted);
  font-size: 8px;
}

.items-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  page-break-inside: auto;
  break-inside: auto;
}

.items-table th,
.items-table td {
  border: 1px solid var(--line) !important;
  padding: 2px 3px !important;
  vertical-align: top !important;
  line-height: 1.12;
}

.items-table thead {
  display: table-header-group;
}

.items-table tr {
  page-break-inside: avoid;
  break-inside: avoid;
}

.items-table thead th {
  background: var(--soft) !important;
  color: var(--brand) !important;
  font-size: 7.2px;
  font-weight: 600;
  text-align: center;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.quotation-items-table td {
  font-size: 7.7px;
}

.quotation-items-table .item-name {
  font-weight: 600;
  margin-bottom: 2px;
}

.quotation-items-table .item-code {
  color: var(--muted);
  font-size: 7px;
  line-height: 1.2;
  white-space: pre-line;
}

.num {
  text-align: right;
  direction: ltr;
  white-space: nowrap;
}

.totals-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 3px;
  page-break-inside: avoid;
  break-inside: avoid;
}

.tax-card,
.totals-card {
  width: 49%;
  vertical-align: top;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}

.summary-spacer {
  width: 2%;
}

.section-kicker {
  color: var(--brand);
  font-weight: 600;
  font-size: 7.4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.totals-table,
.tax-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.totals-table td,
.tax-table td,
.tax-table th {
  border: 1px solid var(--line) !important;
  padding: 2px 3px !important;
  line-height: 1.12;
}

.tax-table th {
  background: var(--soft-2) !important;
  color: var(--brand) !important;
  text-align: left;
  font-size: 7.2px;
  font-weight: 600;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.tax-table .num {
  text-align: right;
  direction: ltr;
}

.totals-table td:first-child {
  color: var(--muted);
  font-weight: 400;
}

.totals-table td:last-child,
.tax-table td:last-child,
.tax-table td.num {
  text-align: right;
  direction: ltr;
}

.totals-table tr:last-child td {
  background: var(--brand) !important;
  color: #ffffff !important;
  font-weight: 600;
  -webkit-text-fill-color: #ffffff !important;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.terms-block {
  margin-top: 5px;
  page-break-inside: avoid;
  break-inside: avoid;
}

.terms-list {
  margin: 0 0 0 16px;
  padding-left: 12px;
  line-height: 1.2;
  font-size: 8.4px;
}

.terms-list li {
  margin: 2px 0;
}

.po-line {
  margin: 8px 0 0 0;
  font-size: 8.6px;
  page-break-inside: avoid;
}

.sign-block {
  margin: 18px 0 0 0;
  font-size: 8.5px;
  page-break-inside: avoid;
}

.sign-block p {
  margin: 0 0 5px 0;
}

.stamp-sign-row {
  display: table;
  width: 240px;
  margin: 6px 0 8px 0;
  table-layout: fixed;
}

.signature-box,
.stamp-box {
  display: table-cell;
  width: 50%;
  vertical-align: middle;
  text-align: left;
}

.signature-box img {
  max-width: 100px;
  max-height: 45px;
  object-fit: contain;
}

.stamp-box img {
  max-width: 90px;
  max-height: 90px;
  object-fit: contain;
}

.email {
  color: #0645ad;
  text-decoration: underline;
}

.currency-symbol {
  font-family: 'SaudiRiyalSymbol', Ubuntu, sans-serif;
  font-size: 1.05em;
  font-weight: normal;
  vertical-align: -0.02em;
}

.page-break {
  page-break-after: always;
  break-after: page;
  height: 0;
  display: block;
}

.footer-page-break {
  page-break-before: auto;
  break-before: auto;
  height: 8mm;
  display: block;
}

.footer-bar {
  position: relative !important;
  left: auto !important;
  right: auto !important;
  bottom: auto !important;

  display: table;
  table-layout: fixed;
  width: 100%;
  min-height: 13mm;

  background-color: var(--blue) !important;
  color: #ffffff !important;

  font-size: 8.8px;
  font-weight: bold;
  padding: 0 8px;
  margin-top: 8mm;

  page-break-inside: avoid;
  break-inside: avoid;

  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.footer-bar span {
  display: table-cell;
  text-align: center;
  vertical-align: middle;

  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;

  padding: 0 3px;
  overflow-wrap: break-word;
  word-break: normal;
}

.footer-bar,
.footer-bar * {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}

@media print {
  .footer-bar {
    position: relative !important;
    background-color: var(--blue) !important;
    color: #ffffff !important;
  }

  .footer-bar,
  .footer-bar * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
}

[dir="rtl"],
.company-info-ar,
.company-name-ar,
.mini-ar,
.party-title span,
.party-rows td:last-child,
.block-head span,
.ar-title {
  font-family: 'Noto Naskh Arabic', serif !important;
}

html:
{# =========================
   CELTCO Quotation Print Format - WITH VAT
   Proforma-style header + Quotation commercial layout
   All VAT columns visible, dynamic tax rate detection
   Completely dynamic — all fields from DocType
   ========================= #}

{% set company = frappe.get_doc("Company", doc.company) if doc.company else None %}

{% set customer = None %}
{% if doc.party_name and frappe.db.exists("Customer", doc.party_name) %}
  {% set customer = frappe.get_doc("Customer", doc.party_name) %}
{% endif %}

{% set company_addr = frappe.get_doc("Address", doc.company_address) if doc.company_address else None %}
{% set customer_addr = frappe.get_doc("Address", doc.customer_address) if doc.customer_address else None %}

{% set company_addr_ar_name = frappe.db.get_value(
  "Address",
  {
    "address_title": "Address Arabic",
    "is_your_company_address": 1,
    "disabled": 0
  },
  "name"
) %}

{% set company_addr_ar = frappe.get_doc("Address", company_addr_ar_name) if company_addr_ar_name else None %}

{% set fallback_logo =
  frappe.db.get_value("File", {"file_name": "Celtco Logo.png"}, "file_url")
  or frappe.db.get_value("File", {"file_name": "Logo.png"}, "file_url")
  or frappe.db.get_value("File", {"file_name": "Logo.jpeg"}, "file_url")
%}

{% set company_logo =
  (company.company_logo if company else None)
  or fallback_logo
  or "/files/Celtco%20Logo.png"
%}

{% set company_en =
  (company.company_name if company else None)
  or "Al-Tamayuz Al-Shamilah Al-Ra'idah Company"
%}

{% set company_ar =
  (company.get("custom_company_name_arabic") if company else None)
  or (company.get("company_name_arabic") if company else None)
  or "شركة التميز الشاملة الرائدة"
%}

{% set company_phone =
  (company.phone_no if company else None)
  or (company_addr.phone if company_addr else None)
  or "0537051718"
%}

{% set company_email =
  (company.email if company else None)
  or (company_addr.email_id if company_addr else None)
  or "ceo@celtco.org"
%}

{% set company_website = (company.website if company else None) or "www.celtco.org" %}
{% set company_vat = doc.company_tax_id or (company.tax_id if company else None) or "312449289400003" %}
{% set company_cr = (company.registration_details if company else None) or (company.get("cr_number") if company else None) or "4650277231" %}

{% set customer_ar =
  (customer.get("customer_name_in_arabic") if customer else None)
  or doc.get("customer_name_in_arabic")
  or doc.customer_name
  or doc.party_name
%}

{% set ref_no = doc.get("custom_reference") or doc.name %}
{% set quote_date = frappe.utils.formatdate(doc.transaction_date, "MMMM d, yyyy") if doc.transaction_date else "" %}

{% set customer_display = doc.customer_name or doc.party_name or "" %}

{% set first_item = doc.items[0] if doc.items else None %}
{% set item_name_fallback = (first_item.item_name or first_item.item_code) if first_item else "Quotation" %}
{% set item_name_fallback = item_name_fallback | striptags | trim %}

{% set scope_text = doc.get("intro_service_text") or "" %}
{% set scope_text = scope_text | striptags | trim %}

{% if not scope_text %}
  {% set scope_text = item_name_fallback %}
{% endif %}

{% set quotation_subject_template = doc.get("print_subject") or "" %}
{% set quotation_subject_template = quotation_subject_template | striptags | trim %}

{% if not quotation_subject_template %}
  {% set quotation_subject_template = "Commercial Proposal: {scope} - {customer}" %}
{% endif %}

{% set quotation_subject =
  quotation_subject_template
  | replace("{customer}", customer_display)
  | replace("{company}", company_en)
  | replace("{scope}", scope_text)
  | replace("{item}", item_name_fallback)
%}

{% set intro_text_template = doc.get("intro_text") or "" %}
{% set intro_text_template = intro_text_template | striptags | trim %}

{% if not intro_text_template %}
  {% set intro_text_template = "With reference to the ongoing collaboration between {company} and {customer}, we are pleased to submit our formal commercial proposal for {scope}." %}
{% endif %}

{% set intro_text =
  intro_text_template
  | replace("{customer}", customer_display)
  | replace("{company}", company_en)
  | replace("{scope}", scope_text)
  | replace("{item}", item_name_fallback)
%}

{% set company_stamp_image =
  (company.get("company_stamp_image") if company else None)
  or (company.get("custom_company_stamp_image") if company else None)
  or ""
%}

{% set company_signature_image =
  (company.get("company_signature_image") if company else None)
  or (company.get("custom_company_signature_image") if company else None)
  or ""
%}

{% set contact_name = doc.contact_display or doc.contact_person or "" %}
{% set contact_mobile = doc.contact_mobile or "" %}
{% set contact_email = doc.contact_email or "" %}

{# =========================
   Dynamic VAT Rate Detection
   Scans doc.taxes for the first non-zero rate
   ========================= #}
{% set tax_ns = namespace(vat_rate=0, has_vat=false) %}

{% for tax in doc.taxes or [] %}
  {% if tax.rate and tax.rate > 0 %}
    {% set tax_ns.vat_rate = frappe.utils.flt(tax.rate) %}
    {% set tax_ns.has_vat = true %}
  {% endif %}
{% endfor %}

{% set vat_rate = tax_ns.vat_rate %}
{% set has_vat = tax_ns.has_vat %}

{# Payment terms - dynamic #}
{% set ps = doc.payment_schedule[0] if doc.payment_schedule else None %}

{% set credit_days = frappe.utils.cint(ps.credit_days) if ps and ps.credit_days else 0 %}
{% set invoice_portion = frappe.utils.flt(ps.invoice_portion) if ps and ps.invoice_portion else 100 %}
{% set payment_term_name = ps.payment_term if ps and ps.get("payment_term") else "" %}

{% if not payment_term_name and doc.get("payment_terms_template") %}
  {% set template_terms = frappe.get_all(
    "Payment Terms Template Detail",
    filters={"parent": doc.payment_terms_template},
    fields=["payment_term", "credit_days", "invoice_portion"],
    order_by="idx asc",
    limit=1
  ) %}

  {% if template_terms %}
    {% set payment_term_name = template_terms[0].payment_term or "" %}
    {% set credit_days = frappe.utils.cint(template_terms[0].credit_days or credit_days) %}
    {% set invoice_portion = frappe.utils.flt(template_terms[0].invoice_portion or invoice_portion) %}
  {% endif %}
{% endif %}

{% set payment_term_key = payment_term_name | lower | trim %}
{% set payment_terms_text = frappe.utils.flt(invoice_portion or 100, 0) ~ "% Advance." %}

{% if "after delivery" in payment_term_key and credit_days %}
  {% set payment_terms_text = frappe.utils.flt(invoice_portion or 100, 0) ~ "% payment shall be processed within " ~ credit_days ~ " days after delivery and invoice submission." %}
{% elif "after invoice" in payment_term_key and credit_days %}
  {% set payment_terms_text = frappe.utils.flt(invoice_portion or 100, 0) ~ "% payment shall be processed within " ~ credit_days ~ " days from the date of invoice." %}
{% elif credit_days %}
  {% set payment_terms_text = frappe.utils.flt(invoice_portion or 100, 0) ~ "% payment shall be processed within " ~ credit_days ~ " days from the date of invoice." %}
{% elif "advance" in payment_term_key %}
  {% set payment_terms_text = frappe.utils.flt(invoice_portion or 100, 0) ~ "% Advance." %}
{% endif %}

{# Money format with Saudi Riyal symbol #}
{% macro money(value) -%}
  {%- set amount = frappe.utils.flt(value or 0, 2) -%}
  <span class="currency-symbol">&#xea;</span>&nbsp;{{ "{:,.2f}".format(amount).replace(".00", "") }}
{%- endmacro %}

{# Amount excluding VAT per row #}
{% macro excl_amount(row) -%}
  {%- if row.net_amount and row.net_amount > 0 -%}
    {{ frappe.utils.flt(row.net_amount, 2) }}
  {%- elif row.amount -%}
    {{ frappe.utils.flt((row.amount or 0) / (1 + (vat_rate or 0) / 100), 2) }}
  {%- else -%}
    {{ frappe.utils.flt(row.amount or 0, 2) }}
  {%- endif -%}
{%- endmacro %}

{# VAT amount per row #}
{% macro item_tax_amount(row) -%}
  {%- if row.get("tax_amount") -%}
    {{ frappe.utils.flt(row.tax_amount, 2) }}
  {%- elif vat_rate and vat_rate > 0 -%}
    {{ frappe.utils.flt(frappe.utils.flt(excl_amount(row), 2) * vat_rate / 100, 2) }}
  {%- else -%}
    0
  {%- endif -%}
{%- endmacro %}

{# Total including VAT per row #}
{% macro item_total_incl_vat(row) -%}
  {{ frappe.utils.flt(excl_amount(row), 2) + frappe.utils.flt(item_tax_amount(row), 2) }}
{%- endmacro %}

{# Compute totals from items #}
{% set total_ns = namespace(excl_total=0, vat_total=0, incl_total=0) %}

{% for row in doc.items or [] %}
  {% set row_excl = frappe.utils.flt(excl_amount(row), 2) %}
  {% set row_vat = frappe.utils.flt(item_tax_amount(row), 2) %}
  {% set total_ns.excl_total = total_ns.excl_total + row_excl %}
  {% set total_ns.vat_total = total_ns.vat_total + row_vat %}
  {% set total_ns.incl_total = total_ns.incl_total + row_excl + row_vat %}
{% endfor %}

<div class="quotation-shell">
  <div class="sheet">

    <div class="company-header-box">
      <table class="company-header-table">
        <tr>
          <td class="company-info-en">
            <div class="company-name-en">{{ company_en }}</div>

            <div class="company-line">
              Building {{ company_addr.address_line2 if company_addr else "-" }},
              {{ company_addr.address_line1 if company_addr else "-" }}
            </div>

            <div class="company-line">{{ company_addr.city if company_addr else "-" }}</div>

            <div class="company-line">
              {{ company_addr.county if company_addr else "-" }},
              {{ company_addr.country if company_addr else "-" }}
              - {{ company_addr.pincode if company_addr else "-" }}
            </div>

            <div class="company-line"><span class="company-label">Mobile:</span> {{ company_phone }}</div>
            <div class="company-line"><span class="company-label">Email:</span> {{ company_email }}</div>
            <div class="company-line"><span class="company-label">Website:</span> {{ company_website }}</div>
            <div class="company-line"><span class="company-label">VAT No:</span> {{ company_vat }}</div>
            <div class="company-line"><span class="company-label">Unified Number:</span> {{ company_cr }}</div>
          </td>

          <td class="company-logo-mid">
            <div class="brand-logo-frame">
              <img class="brand-logo" src="{{ company_logo | replace(' ', '%20') }}" alt="{{ company_en }}">
            </div>

            <div class="invoice-title-center">
              Quotation<br>
              <span class="ar-title">عرض سعر</span>
            </div>
          </td>

          <td class="company-info-ar">
            <div class="company-name-ar">{{ company_ar }}</div>

            <div class="company-line">
              {{ company_addr_ar.address_line2 if company_addr_ar else "-" }}
              {{ company_addr_ar.address_line1 if company_addr_ar else "-" }}
            </div>

            <div class="company-line">
              {{ company_addr_ar.county if company_addr_ar else "-" }}،
              {{ company_addr_ar.country if company_addr_ar else "-" }}
              {{ company_addr_ar.pincode if company_addr_ar else "-" }}
            </div>

            <div class="company-line"><span class="company-label">الجوال:</span> {{ company_phone }}</div>
            <div class="company-line"><span class="company-label">البريد الإلكتروني:</span> {{ company_email }}</div>
            <div class="company-line"><span class="company-label">الموقع الإلكتروني:</span> {{ company_website }}</div>
            <div class="company-line"><span class="company-label">رقم ضريبة القيمة المضافة:</span> {{ company_vat }}</div>
            <div class="company-line"><span class="company-label">الرقم الموحد:</span> {{ company_cr }}</div>
          </td>
        </tr>
      </table>
    </div>

    <table class="summary-grid">
      <tr>
        <td class="summary-card">
          <table class="mini-table">
            <tr>
              <td class="mini-label">Quotation Date</td>
              <td class="mini-value">{{ quote_date or "-" }}</td>
              <td class="mini-ar">تاريخ العرض</td>
            </tr>
            <tr>
              <td class="mini-label">Quotation No</td>
              <td class="mini-value">{{ ref_no }}</td>
              <td class="mini-ar">رقم العرض</td>
            </tr>
            <tr>
              <td class="mini-label">Valid Till</td>
              <td class="mini-value">{{ frappe.utils.formatdate(doc.valid_till, "dd-MM-yyyy") if doc.valid_till else "-" }}</td>
              <td class="mini-ar">صالح حتى</td>
            </tr>
            <tr>
              <td class="mini-label">Customer Ref</td>
              <td class="mini-value">{{ doc.get("po_no") or doc.get("customer_reference") or "-" }}</td>
              <td class="mini-ar">مرجع العميل</td>
            </tr>
          </table>
        </td>
      </tr>
    </table>

    <table class="party-grid">
      <tr>
        <td class="party-column">
          <div class="party-card">
            <div class="party-title"><strong>Seller</strong><span>المورد</span></div>
            <table class="party-rows">
              <tr><td>Name</td><td>{{ company_en }}</td><td>الاسم</td></tr>
              <tr><td>VAT Number</td><td>{{ company_vat }}</td><td>الرقم الضريبي</td></tr>
              <tr><td>Unified Number</td><td>{{ company_cr }}</td><td>الرقم الموحد</td></tr>
              <tr><td>Building No</td><td>{{ (company_addr.address_line2 if company_addr else "") or "-" }}</td><td>رقم المبنى</td></tr>
              <tr><td>Street</td><td>{{ (company_addr.address_line1 if company_addr else "") or "-" }}</td><td>اسم الشارع</td></tr>
              <tr><td>District</td><td>{{ (company_addr.city if company_addr else "") or "-" }}</td><td>الحي</td></tr>
              <tr><td>City / Country</td><td>{{ (company_addr.county if company_addr else "") or "-" }} / {{ (company_addr.country if company_addr else "") or "-" }}</td><td>المدينة / البلد</td></tr>
              <tr><td>Postal Code</td><td>{{ (company_addr.pincode if company_addr else "") or "-" }}</td><td>الرمز البريدي</td></tr>
            </table>
          </div>
        </td>

        <td class="party-gap"></td>

        <td class="party-column">
          <div class="party-card">
            <div class="party-title"><strong>Buyer</strong><span>العميل</span></div>
            <table class="party-rows">
              <tr><td>Name</td><td>{{ doc.customer_name or doc.party_name }}</td><td>الاسم</td></tr>
              <tr><td>VAT Number</td><td>{{ doc.tax_id or (customer.tax_id if customer else None) or "-" }}</td><td>الرقم الضريبي</td></tr>
              <tr><td>Unified Number</td><td>{{ (customer.get("custom_registration_number") if customer else None) or (customer.get("registration_number") if customer else None) or "-" }}</td><td>الرقم الموحد</td></tr>
              <tr><td>Building No</td><td>{{ (customer_addr.address_line2 if customer_addr else "") or "-" }}</td><td>رقم المبنى</td></tr>
              <tr><td>Street</td><td>{{ (customer_addr.address_line1 if customer_addr else "") or "-" }}</td><td>اسم الشارع</td></tr>
              <tr><td>District</td><td>{{ (customer_addr.city if customer_addr else "") or "-" }}</td><td>الحي</td></tr>
              <tr><td>City / Country</td><td>{{ (customer_addr.county if customer_addr else "") or "-" }} / {{ (customer_addr.country if customer_addr else "") or "-" }}</td><td>المدينة / البلد</td></tr>
              <tr><td>Postal Code</td><td>{{ (customer_addr.pincode if customer_addr else "") or "-" }}</td><td>الرمز البريدي</td></tr>
            </table>
          </div>
        </td>
      </tr>
    </table>

    <div class="letter-block">
      <table class="top-info">
        <tr>
          <td class="label-cell"><strong>Subject:</strong></td>
          <td class="value-cell subject-value">
            <strong><u>{{ quotation_subject }}</u></strong>
          </td>
        </tr>
      </table>

      <p class="dear"><strong>Dear Sir,</strong></p>

      <p class="intro">
        {{ intro_text }}
      </p>

      <p class="intro-small">Please find the commercial terms below:</p>
    </div>

    <div class="block">
      <div class="block-head">
        <strong>Commercial Table</strong>
        <span>جدول العرض التجاري</span>
      </div>

      <table class="items-table quotation-items-table">
        <thead>
          <tr>
            <th style="width: 4%;">#</th>
            <th style="width: 46%;">Description / الوصف</th>
            <th style="width: 9%;">Qty / الكمية</th>
            <th style="width: 9%;">Unit / الوحدة</th>
            <th style="width: 13%;">Amount Excl. VAT<br>المبلغ بدون ضريبة</th>
            <th style="width: 9%;">VAT<br>الضريبة</th>
            <th style="width: 10%;">Total Incl. VAT<br>الإجمالي شامل</th>
          </tr>
        </thead>

        <tbody>
          {% for row in doc.items or [] %}
          <tr>
            <td class="num">{{ loop.index }}</td>

            <td>
              <div class="item-name">{{ row.item_name or row.item_code }}</div>
              {% set item_description = (row.description or "") | striptags | trim %}
              {% if item_description and item_description != (row.item_name or "") and item_description != (row.item_code or "") %}
                <div class="item-code">{{ item_description }}</div>
              {% endif %}
            </td>

            <td class="num">
              {{ frappe.utils.flt(row.qty or 0, 2) | int if frappe.utils.flt(row.qty or 0, 2) == (frappe.utils.flt(row.qty or 0, 2) | int) else frappe.utils.flt(row.qty or 0, 2) }}
            </td>

            <td class="num">{{ row.uom or row.stock_uom or "" }}</td>
            <td class="num">{{ money(excl_amount(row)) }}</td>
            <td class="num">{{ money(item_tax_amount(row)) }}</td>
            <td class="num"><strong>{{ money(item_total_incl_vat(row)) }}</strong></td>
          </tr>

          {% if row.page_break %}
        </tbody>
      </table>

      <div class="page-break"></div>

      <table class="items-table quotation-items-table">
        <thead>
          <tr>
            <th style="width: 4%;">#</th>
            <th style="width: 46%;">Description / الوصف</th>
            <th style="width: 9%;">Qty / الكمية</th>
            <th style="width: 9%;">Unit / الوحدة</th>
            <th style="width: 13%;">Amount Excl. VAT<br>المبلغ بدون ضريبة</th>
            <th style="width: 9%;">VAT<br>الضريبة</th>
            <th style="width: 10%;">Total Incl. VAT<br>الإجمالي شامل</th>
          </tr>
        </thead>
        <tbody>
          {% endif %}

          {% endfor %}
        </tbody>
      </table>
    </div>

    <table class="totals-grid">
      <tr>
        <td class="tax-card">
          <div class="section-kicker">Tax Summary</div>
          <table class="tax-table">
            <thead>
              <tr>
                <th>Tax Details</th>
                <th class="num">Taxable Amount</th>
                <th class="num">Tax Amount</th>
              </tr>
            </thead>
            <tbody>
              {% if doc.taxes %}
                {% for tax in doc.taxes %}
                <tr>
                  <td>{{ tax.description or tax.account_head }}</td>
                  <td class="num">{{ money(doc.net_total or total_ns.excl_total) }}</td>
                  <td class="num">{{ money(tax.tax_amount or tax.base_tax_amount or 0) }}</td>
                </tr>
                {% endfor %}
              {% else %}
                <tr>
                  <td>VAT ({{ vat_rate }}%)</td>
                  <td class="num">{{ money(doc.net_total or total_ns.excl_total) }}</td>
                  <td class="num">{{ money(total_ns.vat_total) }}</td>
                </tr>
              {% endif %}
            </tbody>
          </table>
        </td>

        <td class="summary-spacer"></td>

        <td class="totals-card">
          <div class="section-kicker">Total Amounts</div>
          <table class="totals-table">
            <tr>
              <td>Total Excl. VAT</td>
              <td class="num">{{ money(doc.net_total or total_ns.excl_total) }}</td>
            </tr>

            <tr>
              <td>Total VAT ({{ vat_rate }}%)</td>
              <td class="num">{{ money(doc.total_taxes_and_charges or total_ns.vat_total) }}</td>
            </tr>

            {% if doc.discount_amount %}
            <tr>
              <td>Discount</td>
              <td class="num">{{ money(doc.discount_amount) }}</td>
            </tr>
            {% endif %}

            <tr>
              <td>Grand Total Incl. VAT</td>
              <td class="num">{{ money(doc.grand_total or doc.rounded_total or total_ns.incl_total) }}</td>
            </tr>
          </table>
        </td>
      </tr>
    </table>

    <div class="block terms-block">
      <div class="block-head">
        <strong>Terms and Conditions</strong>
        <span>الشروط والأحكام</span>
      </div>

      <ul class="terms-list">
        <li><strong>Payment Terms:</strong> {{ payment_terms_text }}</li>
      </ul>
    </div>

    <p class="po-line"><strong>Please acknowledge this quotation by issuing a formal Purchase Order (PO).</strong></p>

    <div class="sign-block">
      <p><strong>Best Regards,</strong></p>

      <div class="stamp-sign-row">
        {% if company_signature_image %}
          <div class="signature-box">
            <img src="{{ company_signature_image | replace(' ', '%20') }}" alt="Signature">
          </div>
        {% endif %}

        {% if company_stamp_image %}
          <div class="stamp-box">
            <img src="{{ company_stamp_image | replace(' ', '%20') }}" alt="Company Stamp">
          </div>
        {% endif %}
      </div>

      <p><strong>{{ doc.get("custom_signatory_name") or "Salman Muhammad" }}</strong></p>
      <p><strong>{{ company_en }} (CELTCO)</strong></p>
      <p>Mob no: [{{ doc.get("custom_signatory_mobile") or "0537051718" }}]</p>
      <p>Email: [ <span class="email">{{ doc.get("custom_signatory_email") or "Operation@celtco.org" }}</span> ]</p>
    </div>

    <div class="footer-page-break"></div>

    <div class="footer-bar">
      <span>📍 {{ (company_addr.city if company_addr else "") or "Al Madina Bani Dhafir Dist." }}</span>
      <span>☎ {{ company_phone }}</span>
      <span>🌐 {{ company_email }}</span>
      <span>CR No: {{ company_cr }}</span>
    </div>

  </div>
</div>
